approaches.person-from-payload:
"""A door names a person the roadmap already names (approach person-from-payload)."""
import re

DOOR = re.compile(r"^unassigned — (?P<who>.+?) by (?P<when>.+)$")
PERSON = re.compile(r"^(?:[A-Z][\w'’-]+)(?:\s+[A-Z][\w'’-]+)+$")


def named_people(pack):
    people = set()
    decider = str((pack.get("platform_approval") or {}).get("decided_by") or "").strip()
    if decider:
        people.add(decider)
    for row in pack.get("ownership") or []:
        owner = str(row.get("owner") or "").strip()
        if owner.lower().startswith("unassigned"):
            continue
        first = re.split(r"[,;(]| for | with ", owner, maxsplit=1)[0].strip()
        if PERSON.match(first):
            people.add(first)
    return people


def apply(case):
    pack = case["pack"]
    people = named_people(pack)
    bad = []
    doors = []
    for index, row in enumerate(pack.get("ownership") or []):
        owner = str(row.get("owner") or "").strip()
        match = DOOR.match(owner)
        if not match:
            continue
        who = re.sub(r"\s+must assign it$", "", match.group("who").strip())
        if who not in people:
            bad.append(f"ownership[{index}] ({row.get('element')}) says {who!r} must assign the owner")
        doors.append(f"- **Assign the {row.get('element')} owner** — {owner[len('unassigned — '):]}")
    if bad:
        raise ValueError(
            "tactical_roadmap_door_assigner_unnamed: a door names a person this roadmap already "
            "names as the platform decider or as an owner, never a role or a new name — the people "
            f"available are {sorted(people)}; fix every row: " + "; ".join(bad) + "."
        )
    return {"refusal": None, "rendered": "\n".join(doors), "pack": pack}
